    public EdtEditorOpenTool(){super("open","Open an existing .mdo object, .form, or .bsl module in EDT. Optional 1-based line applies only to .bsl. For BSL navigation, or activate_window=true on a form or metadata object, restores a minimized EDT window and requests foreground activation. Returns the verified line and navigation_state. opened_in_background confirms navigation; report that EDT stayed in the background. Never saves or changes sources.","{\"type\": \"object\", \"additionalProperties\": false, \"properties\": {\"activate_window\": {\"type\": \"boolean\", \"description\": \"Request foreground activation for a form or metadata editor.\"}, \"line\": {\"type\": \"integer\", \"minimum\": 1}, \"project\": {\"type\": \"string\"}, \"expected_project_path\": {\"type\": \"string\", \"description\": \"Optional absolute local project directory. Checked before any editor opens.\"}, \"file_path\": {\"type\": \"string\", \"description\": \"Path relative to project src/, e.g. Documents/РегистрацияГрузовыхМест/РегистрацияГрузовыхМест.mdo or Documents/РегистрацияГрузовыхМест/Forms/ФормаДокумента/Form.form\"}}, \"required\": [\"project\", \"file_path\"]}");}
